let posx = Math.random(1e10);
let posy = Math.random(1e10);
let variation = 0;
let maxRectSize;
let minRectSize;
const stackDepth = 9;

setup = () => {
	p5.disableFriendlyErrors = true;

  createCanvas(windowWidth, windowHeight);
  maxRectSize = max(width, height);
  minRectSize = maxRectSize / (2 ** stackDepth);
  rectMode(CENTER);
  stroke("black");
  noFill();
};

draw = () => {
  background("white");
  variation += 0.003;
  quadTree(width / 2, height / 2, maxRectSize);
};

mouseDragged = () => {
  posx += (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  posy += (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
};

quadTree = (x, y, size) => {
  if (size < minRectSize) return;
  const n = noise((x + posx) * 0.001, (y + posy) * 0.001, variation);
  if (abs(n - 0.45) > size / maxRectSize) {
    rect(x, y, size);
  } else {
    size /= 2;
    const d = size / 2;
    quadTree(x + d, y + d, size);
    quadTree(x + d, y - d, size);
    quadTree(x - d, y + d, size);
    quadTree(x - d, y - d, size);
  }
};

